import cpmpy as cp
import json

X = -1
game_data = [  # 0-8: number of mines around, -1: not opened
    [2, 3, X, 2, 2, X, 2, 1],
    [X, X, 4, X, X, 4, X, 2],
    [X, X, X, X, X, X, 4, X],
    [X, 5, X, 6, X, X, X, 2],
    [2, X, X, X, 5, 5, X, 2],
    [1, 3, 4, X, X, X, 4, X],
    [0, 1, X, 4, X, X, X, 3],
    [0, 1, 2, X, 2, 3, X, 2]
]

rows = len(game_data)
cols = len(game_data[0])

# Decision variables: mines[i][j] = 1 if cell (i,j) is a mine, else 0
mines = [[cp.IntVar(0,1) for j in range(cols)] for i in range(rows)]

model = cp.Model()

# Helper function to get neighbors of a cell
def neighbors(i,j):
    for di in [-1,0,1]:
        for dj in [-1,0,1]:
            ni, nj = i+di, j+dj
            if 0 <= ni < rows and 0 <= nj < cols:
                if not (di == 0 and dj == 0):
                    yield ni, nj

# Constraints:
# For each cell with a clue (0-8), sum of mines in neighbors must equal clue
for i in range(rows):
    for j in range(cols):
        clue = game_data[i][j]
        if clue != X:
            # sum of mines in neighbors == clue
            model += cp.sum([mines[ni][nj] for (ni,nj) in neighbors(i,j)]) == clue

# For cells that are opened (clue != X), they cannot be mines
for i in range(rows):
    for j in range(cols):
        if game_data[i][j] != X:
            model += mines[i][j] == 0

# Solve and print
if model.solve():
    solution = {'mines': [[int(mines[i][j].value()) for j in range(cols)] for i in range(rows)]}
    print(json.dumps(solution, indent=4))
else:
    print("No solution found.")
```

